{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Practical Aromatherapy VIP Day</title>
  <meta name="description" content="A safety-first aromatherapy VIP Day for practitioners and curious clients. Practical guidance, curated blends, and bespoke plans." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="nav-shell">
    <div class="nav-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <button id="nav-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button>
      <nav id="site-nav" class="site-nav" aria-label="Main">
        <ul>
          <li><a href="/">Welcome</a></li>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="blends.html">Blends & Notes</a></li>
          <li><a href="shop.html">Boutique</a></li>
          <li><a href="pricing.html">Invest</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="book.html" class="primary">Book a VIP Day</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero (practical, safety-first) -->
    <section id="hero" class="hero glass">
      <div class="hero-inner">
        <div class="hero-copy">
          <h1>{{TAGLINE}}</h1>
          <p class="lead">Hands-on aromatherapy planning for busy people who want clear steps, safe practices, and blends that actually fit daily life. VIP Day available — leave with a personalized plan and starter kit.</p>
          <div class="hero-ctas">
            <a href="{{PRIMARY_CTA_URL}}" class="btn btn-primary ripple">{{PRIMARY_CTA_LABEL}}</a>
            <a href="#lead-magnet" class="btn btn-outline">Get a free guide</a>
          </div>
          <p class="safety">Safety-first: aromatherapy guidance is educational and not medical advice. Always patch test and follow dilution guidance.</p>
        </div>
        <div class="hero-graphic">
          <svg viewBox="0 0 320 220" class="bottle" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#D6FAE3" />
                <stop offset="1" stop-color="#EAF6FF" />
              </linearGradient>
            </defs>
            <rect rx="18" x="12" y="12" width="296" height="196" fill="url(#g1)" opacity="0.9" />
            <g fill="#2b2b2b" opacity="0.08">
              <ellipse cx="160" cy="170" rx="90" ry="18" />
            </g>
            <g class="leaf" transform="translate(40,40)">
              <path d="M50 30 C65 10, 110 10, 120 30 C110 45, 65 60, 50 45 Z" fill="#8ED1B2" />
            </g>
          </svg>
        </div>
      </div>
      <svg class="pattern-bg" aria-hidden="true"><use href="assets/img/pattern.svg#pattern" /></svg>
    </section>

    <!-- Social proof (testimonials) -->
    <section id="social" class="social glass">
      <h2>Trusted by clients and colleagues</h2>
      <div class="testimonials">
        <blockquote>
          "Practical, clear, and refreshingly safe. My diffuser blends now have purpose." — A.C., {{CITY}}
        </blockquote>
        <blockquote>
          "The VIP Day gave me a ready-to-use plan and a confidence boost for my practice." — M.R., practitioner
        </blockquote>
        <div class="meta">Featured in local wellness collectives. Phone: {{PHONE}}</div>
      </div>
    </section>

    <!-- Benefits (straightforward list) -->
    <section id="benefits" class="benefits">
      <h2>What you'll gain</h2>
      <ul class="benefit-list">
        <li>
          <h3>Clear safety guidance</h3>
          <p>Learn dilution, storage, and pet- and pregnancy-conscious practices so you can use oils responsibly.</p>
        </li>
        <li>
          <h3>Practical blends</h3>
          <p>Custom blends that match your daily routines — no complicated rituals.</p>
        </li>
        <li>
          <h3>Tools & resources</h3>
          <p>Starter kit templates, printable labels, and a simple follow-up plan tailored to you.</p>
        </li>
      </ul>
    </section>

    <!-- Process (step-by-step VIP Day) -->
    <section id="process" class="process glass">
      <h2>How the VIP Day works</h2>
      <ol>
        <li><strong>Pre-brief:</strong> Quick questionnaire so the day is focused on your needs.</li>
        <li><strong>Session:</strong> Full-day in-person or virtual deep-dive — blending, safety checks, and labeling.</li>
        <li><strong>Takeaway:</strong> A starter kit list, dilution cards, and a one-sheet follow-up plan.</li>
      </ol>
      <p class="note">Sessions are educational and safety-focused. We do not diagnose or treat medical conditions.</p>
    </section>

    <!-- FAQ (safety-forward) -->
    <section id="faq" class="faq">
      <h2>Common questions</h2>
      <details>
        <summary>How should I dilute essential oils?</summary>
        <div class="answer">Dilution depends on age, use, and oil. Typical adult topical dilutions range from 1%–3% for daily creams/roll-ons. We cover exact math during the VIP Day and provide dilution cards. Always follow safety data for each oil.</div>
      </details>
      <details>
        <summary>What is a patch test?</summary>
        <div class="answer">A patch test applies a small diluted amount to skin for 24 hours to check for irritation. We'll show the correct method and what to watch for.</div>
      </details>
      <details>
        <summary>Are essential oils safe around pets?</summary>
        <div class="answer">Some oils can be harmful to pets. We emphasize pet-safe choices and diffusion patterns to minimize risk. Consult your veterinarian for concerns.</div>
      </details>
      <details>
        <summary>What about pregnancy?</summary>
        <div class="answer">Pregnancy requires extra caution. Certain oils and higher concentrations are not recommended. We provide pregnancy-safe alternatives and refer to medical guidance when appropriate.</div>
      </details>
    </section>

    <!-- Lead magnet (email capture) -->
    <section id="lead-magnet" class="lead-magnet glass">
      <h2>Free guide: Safe Starter Blends</h2>
      <p>Get a printable guide with dilution cards and four easy blends to try at home.</p>
      <form id="lead-form" class="lead-form" autocomplete="on">
        <label for="lead-email">Email</label>
        <input id="lead-email" name="email" type="email" placeholder="you@example.com" required />
        <button type="submit" class="btn btn-primary ripple">Send the guide</button>
        <p class="consent">By signing up you agree to receive occasional emails. We never sell your info.</p>
      </form>
      <div id="lead-success" class="lead-success" hidden>
        <p>Thank you — your guide is on the way. Check your inbox for a print-friendly PDF and safe-use tips.</p>
      </div>
    </section>

    <!-- CTA (book a VIP Day) -->
    <section id="cta" class="cta glass">
      <h2>Ready for a focused VIP Day?</h2>
      <p>Spend one day learning practical blending, safety checks, and a follow-up plan. Ideal for new practitioners, studio owners, or anyone wanting confidence with oils.</p>
      <a href="{{PRIMARY_CTA_URL}}" class="btn btn-primary ripple">Book a VIP Day</a>
      <p class="contact">Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>

  </main>

  <footer class="site-footer">
    <div class="footer-inner">
      <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}} • Practitioner: {{PRACTITIONER_NAME}}</div>
      <nav class="foot-nav">
        <a href="about.html">Our Story</a>
        <a href="contact.html">Get in touch</a>
        <a href="shop.html">Shop</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
