{"path":"assets/css/styles.css","content":"/* Glass-morphism aromatherapy template styles */
:root{
  --bg1:#f6fbff;
  --accent1:#7fd3b6;
  --accent2:#8ec6ff;
  --glass-bg:rgba(255,255,255,0.55);
  --muted:#6b7280;
  --radius:14px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:linear-gradient(180deg,var(--bg1),#f0fbf6); color:#123;}
body{display:flex;flex-direction:column;align-items:stretch}
.nav-shell{backdrop-filter:blur(6px);background:linear-gradient(90deg, rgba(255,255,255,0.45), rgba(240,250,255,0.35));border-bottom:1px solid rgba(255,255,255,0.6);}
.nav-inner{max-width:var(--max-width);margin:0 auto;padding:18px;display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:#0f172a;text-decoration:none}
#nav-toggle{display:none;padding:8px 10px;border-radius:10px;border:1px solid rgba(0,0,0,0.06);background:transparent}
.site-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:12px}
.site-nav a{color:#0f172a;text-decoration:none;padding:8px 10px;border-radius:8px}
.site-nav a.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:white}
main{max-width:var(--max-width);width:100%;margin:28px auto;padding:0 18px}
.glass{background:var(--glass-bg);border-radius:var(--radius);padding:22px;margin:18px 0;box-shadow:0 6px 18px rgba(15,23,42,0.06);border:1px solid rgba(255,255,255,0.6)}
.hero{display:flex;align-items:center;justify-content:center;padding:28px}
.hero-inner{display:flex;gap:28px;align-items:center;width:100%}
.hero-copy{flex:1}
.hero h1{font-size:1.8rem;margin:0 0 10px}
.lead{color:var(--muted);margin:0 0 16px}
.hero-ctas{display:flex;gap:10px;align-items:center}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid rgba(15,23,42,0.06)}
.btn-primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:white;border:none}
.btn-outline{background:transparent;border:1px solid rgba(15,23,42,0.06);color:var(--muted)}
.bottle{width:260px;height:auto}
.pattern-bg{position:absolute;right:18px;top:18px;width:220px;height:220px;opacity:0.14}
.safety{font-size:0.85rem;color:var(--muted);margin-top:10px}
.social h2,.benefits h2,.process h2,.faq h2,.lead-magnet h2,.cta h2{margin-top:6px}
.testimonials{display:flex;gap:12px;flex-wrap:wrap}
.testimonials blockquote{background:transparent;padding:12px;border-radius:10px;border:1px dashed rgba(15,23,42,0.06);min-width:220px}
.benefit-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;padding:0;list-style:none}
.benefit-list h3{margin:0 0 6px}
.process ol{padding-left:18px}
.faq details{margin:10px 0;padding:10px;border-radius:10px;background:linear-gradient(180deg, rgba(255,255,255,0.4), rgba(255,255,255,0.2));}
.lead-form{display:flex;gap:8px;align-items:center}
.lead-form input[type="email"]{flex:1;padding:10px;border-radius:8px;border:1px solid rgba(15,23,42,0.06)}
.lead-success{padding:12px;background:#e8fff3;border-radius:10px;border:1px solid rgba(15,23,42,0.04)}
.cta{text-align:center}
.site-footer{margin-top:28px;padding:18px;background:transparent}
.footer-inner{max-width:var(--max-width);margin:0 auto;display:flex;justify-content:space-between;align-items:center;padding:6px 18px}
.foot-nav a{margin-left:12px;color:var(--muted);text-decoration:none}
/* Responsive */
@media (max-width:820px){
  .hero-inner{flex-direction:column}
  #nav-toggle{display:inline-block}
  .site-nav{display:none}
  .site-nav.open{display:block}
  .site-nav ul{flex-direction:column;background:rgba(255,255,255,0.7);padding:8px;border-radius:8px}
}
/* Ripple effect */
.ripple{position:relative;overflow:hidden}
.ripple::after{content:"";position:absolute;border-radius:50%;transform:scale(0);opacity:0.6;background:rgba(255,255,255,0.4);width:120px;height:120px;left:50%;top:50%;pointer-events:none;transition:transform 0.6s ease,opacity 0.8s}
.ripple:active::after{transform:translate(-50%,-50%) scale(1);opacity:0}
/* small utilities */
.note{font-size:0.9rem;color:var(--muted)}"} 
{"path":"assets/js/main.js","content":"// Minimal interactive behaviors: mobile nav, lead capture, accessibility
document.addEventListener('DOMContentLoaded',function(){
  var navToggle = document.getElementById('nav-toggle');
  var siteNav = document.getElementById('site-nav');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      siteNav.classList.toggle('open');
    });
  }

  // Lead magnet form: fake submit and show success message
  var leadForm = document.getElementById('lead-form');
  var leadSuccess = document.getElementById('lead-success');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email = leadForm.email.value.trim();
      if(!email || email.indexOf('@')===-1){
        alert('Please enter a valid email.');
        return;
      }
      // Simulate network and reveal success
      leadForm.querySelector('button').disabled = true;
      leadForm.querySelector('button').textContent = 'Sending...';
      setTimeout(function(){
        leadForm.hidden = true;
        leadSuccess.hidden = false;
        // simple localStorage flag so returning user sees thank-you
        try{localStorage.setItem('lead_signed','1')}catch(e){}
      },800);
    });
  }

  // small enhancement: make details summary keyboard-friendly
  document.querySelectorAll('details summary').forEach(function(s){
    s.addEventListener('keydown',function(e){
      if(e.key === 'Enter' || e.key === ' '){
        e.preventDefault(); this.parentElement.open = !this.parentElement.open;
      }
    });
  });

  // Accessibility focus outline toggle
  function handleFirstTab(e) {
    if(e.key === 'Tab'){
      document.body.classList.add('user-is-tabbing');
      window.removeEventListener('keydown', handleFirstTab);
    }
  }
  window.addEventListener('keydown', handleFirstTab);
});"} 
